// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FleetMember) predicate.FleetMember {
	return predicate.FleetMember(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FleetMember) predicate.FleetMember {
	return predicate.FleetMember(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FleetMember) predicate.FleetMember {
	return predicate.FleetMember(sql.NotPredicates(p))
}
